const ROOM_NAME = 'Room 101';
const EXISTING_BOOKINGS = [{ start: 600, end: 660 }];

function minutesToHHMM(minutes) {
    if (minutes === null || minutes === undefined || Number.isNaN(minutes)) return '--:--';
    const clamped = Math.max(0, Math.min(1440, minutes));
    const h = Math.floor(clamped / 60);
    const m = clamped % 60;
    return String(h).padStart(2, '0') + ':' + String(m).padStart(2, '0');
}

function parseClock(value, fieldName) {
    if (typeof value === 'number') {
        if (!Number.isFinite(value) || !Number.isInteger(value)) {
            return { ok: false, message: fieldName + ' must be an integer number of minutes or HH:MM.' };
        }
        if (value < 0 || value > 1440) {
            return { ok: false, message: fieldName + ' must be between 00:00 and 24:00 (0–1440 minutes).' };
        }
        return { ok: true, minutes: value };
    }
    const raw = String(value ?? '').trim();
    if (raw === '') {
        return { ok: false, message: 'Please enter a value for ' + fieldName + '.' };
    }
    if (raw === '24:00' || raw === '24:00:00') {
        return { ok: true, minutes: 1440 };
    }
    const hm = /^([01]?\d|2[0-3]):([0-5]\d)(?::[0-5]\d)?$/.exec(raw);
    if (hm) {
        return { ok: true, minutes: parseInt(hm[1], 10) * 60 + parseInt(hm[2], 10) };
    }
    if (/^-?\d+$/.test(raw)) {
        const minutes = parseInt(raw, 10);
        if (minutes < 0 || minutes > 1440) {
            return { ok: false, message: fieldName + ' must be between 00:00 and 24:00 (0–1440 minutes).' };
        }
        return { ok: true, minutes };
    }
    return { ok: false, message: fieldName + ' must be HH:MM or an integer number of minutes from midnight.' };
}

function parseDuration(value) {
    let duration;
    if (typeof value === 'number') {
        duration = value;
    } else if (typeof value === 'boolean') {
        return { ok: false, reasonCode: 'invalid_duration', message: 'Duration must be a whole number of minutes.' };
    } else {
        const raw = String(value ?? '').trim();
        if (raw === '') {
            return { ok: false, reasonCode: 'invalid_duration', message: 'Please enter a duration in minutes.' };
        }
        if (!/^-?\d+$/.test(raw)) {
            return { ok: false, reasonCode: 'invalid_duration', message: 'Duration must be a whole number of minutes.' };
        }
        duration = parseInt(raw, 10);
    }
    if (!Number.isFinite(duration) || !Number.isInteger(duration)) {
        return { ok: false, reasonCode: 'invalid_duration', message: 'Duration must be a whole number of minutes.' };
    }
    if (duration <= 0) {
        return { ok: false, reasonCode: 'invalid_duration', message: 'Duration must be greater than 0 minutes.' };
    }
    if (duration > 120) {
        return { ok: false, reasonCode: 'duration_too_long', message: 'Duration must be at most 120 minutes (requested ' + duration + ').' };
    }
    return { ok: true, duration };
}

function validateRequest(input) {
    const nowParsed = parseClock(input.now, 'Reference current time');
    if (!nowParsed.ok) {
        return { ok: false, available: false, reasonCode: 'invalid_now', message: nowParsed.message };
    }
    if (nowParsed.minutes >= 1440) {
        return { ok: false, available: false, reasonCode: 'invalid_now', message: 'Reference current time must be between 00:00 and 23:59.' };
    }
    const startParsed = parseClock(input.startTime, 'Start time');
    if (!startParsed.ok) {
        return { ok: false, available: false, reasonCode: 'invalid_start', message: startParsed.message };
    }
    const durationParsed = parseDuration(input.duration);
    if (!durationParsed.ok) {
        return { ok: false, available: false, reasonCode: durationParsed.reasonCode, message: durationParsed.message };
    }
    const start = startParsed.minutes;
    const duration = durationParsed.duration;
    const end = start + duration;
    if (end > 1440) {
        return {
            ok: false,
            available: false,
            reasonCode: 'invalid_range',
            message: 'Start time ' + minutesToHHMM(start) + ' plus duration ' + duration + ' minutes extends past 24:00.'
        };
    }
    if (start <= nowParsed.minutes) {
        return {
            ok: false,
            available: false,
            reasonCode: 'past_start',
            message: 'Start time ' + minutesToHHMM(start) + ' must be after the current time ' + minutesToHHMM(nowParsed.minutes) + '.'
        };
    }
    return { ok: true, start, end, duration, now: nowParsed.minutes };
}

function checkAvailability(input) {
    const bookings = EXISTING_BOOKINGS;
    const before = JSON.stringify(bookings);
    const validated = validateRequest(input);
    let result;
    if (!validated.ok) {
        result = { available: false, reasonCode: validated.reasonCode, message: validated.message };
    } else if (input.isBlocked === true || input.isBlocked === 'true' || input.isBlocked === 'on' || input.isBlocked === 1) {
        result = { available: false, reasonCode: 'blocked', message: ROOM_NAME + ' is blocked and unavailable for any booking.' };
    } else {
        let overlap = null;
        // Visual switch nodes cannot loop over a booking array; this small JS
        // Function node is the deterministic rule engine (limitation recorded in the report).
        for (let i = 0; i < bookings.length; i++) {
            const booking = bookings[i];
            if (validated.start < booking.end && booking.start < validated.end) {
                overlap = booking;
                break;
            }
        }
        if (overlap) {
            result = {
                available: false,
                reasonCode: 'overlap',
                message: 'Requested interval ' + minutesToHHMM(validated.start) + '–' + minutesToHHMM(validated.end) +
                    ' overlaps an existing booking ' + minutesToHHMM(overlap.start) + '–' + minutesToHHMM(overlap.end) + '.'
            };
        } else {
            result = {
                available: true,
                reasonCode: 'available',
                message: ROOM_NAME + ' is available from ' + minutesToHHMM(validated.start) + ' to ' + minutesToHHMM(validated.end) +
                    ' (' + validated.duration + ' min).'
            };
        }
    }
    const after = JSON.stringify(bookings);
    result.existingBookings = JSON.parse(JSON.stringify(EXISTING_BOOKINGS));
    result.bookingsUnchanged = before === after && after === JSON.stringify([{ start: 600, end: 660 }]);
    return result;
}

function normalizeRequest(raw) {
    const src = (raw && typeof raw === 'object' && !Array.isArray(raw)) ? raw : {};
    let isBlocked = src.isBlocked;
    if (isBlocked === undefined) isBlocked = src.blocked;
    if (typeof isBlocked === 'string') {
        const lowered = isBlocked.toLowerCase();
        isBlocked = (lowered === 'true' || lowered === 'on' || lowered === '1' || lowered === 'yes');
    }
    return {
        startTime: src.startTime !== undefined ? src.startTime : (src.start !== undefined ? src.start : ''),
        duration: src.duration !== undefined ? src.duration : '',
        isBlocked: Boolean(isBlocked),
        now: (src.now !== undefined && src.now !== '') ? src.now : ((src.referenceTime !== undefined && src.referenceTime !== '') ? src.referenceTime : '09:00')
    };
}

let raw = msg.payload;
if ((!raw || typeof raw !== 'object' || Array.isArray(raw)) && msg.req && msg.req.query) {
    raw = msg.req.query;
}
msg.request = normalizeRequest(raw);
msg.payload = msg.request;
return msg;

